                "content": "(가) 저 건너 ⓐ꽁생원은 팔자를 원망토다 제 아비 덕분으로 돈천이나 가졌더니 술 한 잔 밥 한 술을 친구 대접 하였던가 주제넘게 아는 체로 ㉠음양술수(陰陽術數) 현혹되어 이장도 자주 하며 이사도 힘을 쓰고 당대발복(當代發福) 예 아니면 피란처가 여기로다 올 적 갈 적 행로상에 ㉡처자식을 흩어 놓고 유무(有無) 상관 아니하고 공것을 바라도다 기인취물(欺人取物) 하자 하니 두 번째는 아니 속고 공납(公納) 범용 하자 하니 일가 중에 부자 없고 뜬재물을 경영하여 경향출입 싸다닐 제 재상가에 ㉢청질하다 봉변당해 물러서며 남의 고을 걸태 하다 혼금(閽禁)에 쫓겨 오기 혼인 중매 선채* 돈에 창피당해 뺨 맞으며 가대* 흥정 구문 먹기 ㉣핀잔 듣고 자빠지고 불의행실(不義行實) 찌그렁이 위조문서 비리호송(非理好訟) 부자나 후려 볼까 ㉤감언이설 꾀어 보자 언막이에 보막이며 은광이며 금광이라 큰길가에 색주가며 노름판에 푼돈 떼기 남북촌에 뚜쟁이로 인물 초인(招引) 하여 볼까 산진매 수진매로 사냥질로 놀아나기 혼인 핑계 어린 딸이 백 냥짜리 되었구나 대종손 양반 자랑 산소나 팔아 볼까 아낙은 친정살이 자식은 머슴살이 일가에게 인심 잃고 친구에게 손가락질 부지거처(不知去處) 나간 후에 소문이나 들었던가 -작자 미상, ｢우부가｣- *선채(先綵): 혼례 전에 신랑 집에서 신부 집으로 보내는 비단."
